steps.probe:
(() => { 
  const mark = window.__hb.mark;
  const genAtMark = window.__hb.genAtMark;
  const S = window.__hb.samples.filter((x) => x.t >= mark);
  const oldBar = S.filter((x) => x.gen === genAtMark && x.n > 0);
  const fresh = S.filter((x) => x.gen !== genAtMark && x.n >= 0);
  const hostAt = fresh.length > 0 ? fresh[0] : null;
  const newGen = hostAt === null ? 0 : hostAt.gen;
  const inNew = S.filter((x) => x.gen === newGen);
  const content = inNew.find((x) => x.n > 0);
  const chip = inNew.find((x) => x.chips > 0);
  const afterChip = chip === undefined ? [] : inNew.filter((x) => x.t > chip.t);
  const lost = afterChip.filter((x) => x.chips === 0);
  window.__hb.iv && clearInterval(window.__hb.iv);
  return ({
    samples: S.length,
    oldBarLastAtMs: oldBar.length === 0 ? -1 : oldBar[oldBar.length - 1].t - mark,
    newHostAtMs: hostAt === null ? -1 : hostAt.t - mark,
    newHostFirst: inNew.slice(0, 4).map((x) => ({ dt: x.t - mark, n: x.n, chips: x.chips, empty: x.empty, text: x.text })),
    newHostContentAtMs: content === undefined ? -1 : content.t - mark,
    newHostBlankMs: (hostAt === null || content === undefined) ? -1 : content.t - hostAt.t,
    newHostChipAtMs: chip === undefined ? -1 : chip.t - mark,
    lostChipSamples: lost.length,
    newHostLast: inNew.length === 0 ? null : { dt: inNew[inNew.length - 1].t - mark, n: inNew[inNew.length - 1].n, chips: inNew[inNew.length - 1].chips, text: inNew[inNew.length - 1].text }
  });
 })()
